# -- .column_grad: per-fiber subgradient ------------------------------
## CVXPY SOURCE: atoms/geo_mean.py GeoMean._column_grad (lines 310-320);
## _grad (lines 322-333) is AxisAtom._axis_grad, which walks the fibers
## (method(.grad, AxisAtom)).
## D[i] = w[i] / x[i] * geo_mean(x; w) on kept entries, 0 elsewhere.
## Domain: NULL if any kept entry is <= 0.
## w may be bigq; coerce via as.numeric (CVXPY's float(w_i)).
method(.column_grad, GeoMean) <- function(x, value, ...) {
  column <- as.numeric(value)
  kept <- column[x@.keep]
  w <- as.numeric(x@w)
  if (any(kept <= 0)) return(NULL)
  gm_val <- prod(kept^w)
  D <- numeric(length(column))
  D[x@.keep] <- w / kept * gm_val
  D
}

# ===================================================================
# GeoMeanApprox -- SOC-based rational approximation of GeoMean
# ===================================================================
## CVXPY SOURCE: atoms/geo_mean.py lines 418-481
## Subclass of GeoMean. Overrides w with rational approximation
## and adds w_dyad (dyadic completion), tree (decomposition),
## cone_lb, cone_num_over, cone_num.

GeoMeanApprox <- new_class("GeoMeanApprox", parent = GeoMean, package = "CVXR",
  properties = list(
    w_dyad        = new_property(class = class_any),       # bigq dyadic completion
    tree          = new_property(class = class_any),       # decomposition tree
    cone_lb       = new_property(class = class_integer),
    cone_num_over = new_property(class = class_integer),
    cone_num      = new_property(class = class_integer)
  ),
  constructor = function(x, p = NULL, max_denom = 1024L, axis = NULL,
                         keepdims = FALSE, id = NULL) {
    if (FALSE) new_object(S7_object())  ## S7 static-check guard
    if (is.null(id)) id <- next_expr_id()
    init <- .gm_init(x, p, axis, keepdims)
    p <- init$p

    ## Rational approximation via fracify (CVXPY geo_mean.py line 456)
    frac_result <- fracify(p, max_denom)
    w <- frac_result$w
    w_dyad <- frac_result$w_dyad
    ae <- approx_error(p, w)

    ## Decompose for SOC construction (CVXPY geo_mean.py line 459)
    tree_result <- decompose(w_dyad)

    ## Cone bounds (CVXPY geo_mean.py lines 462-468)
    clb <- lower_bound(w_dyad)
    cno <- over_bound(w_dyad, tree_result)
    cn <- clb + cno

    obj <- .fast_new(GeoMeanApprox, S7_object(),
      id            = as.integer(id),
      .cache        = new.env(parent = emptyenv()),
      args          = list(init$x),
      shape         = init$shape,
      axis          = init$axis,
      keepdims      = init$keepdims,
      p             = p,
      w             = w,
      max_denom     = as.integer(max_denom),
      approx_error  = ae,
      .keep         = init$keep,
      w_dyad        = w_dyad,
      tree          = tree_result,
      cone_lb       = as.integer(clb),
      cone_num_over = as.integer(cno),
      cone_num      = as.integer(cn)
    )
    validate_arguments(obj)
    obj
  }
)

# -- Factory function ---------------------------------------------
#' (Weighted) geometric mean
#'
#' The (weighted) geometric mean of the entries of `x`, of all of them or of
#' each row or column.
#'
#' @param x An Expression of any shape. With `axis = NULL` its entries are
#'   taken in column-major order, so a row vector, a column vector and a
#'   matrix holding the same entries give the same result.
#' @param p Numeric weight vector (default: uniform), one weight per entry
#'   being reduced: `length(x)` entries with `axis = NULL`, `ncol(x)` with
#'   `axis = 1`, `nrow(x)` with `axis = 2`. Entries with zero weight take no
#'   part.
#' @param max_denom Maximum denominator for rational approximation
#' @param approx If TRUE (default), use SOC approximation. If FALSE, use exact power cone.
#' @param axis `NULL` (default) for one geometric mean of all entries, `1` for
#'   one per row, `2` for one per column.
#' @param keepdims Keep the reduced dimension with length one.
#' @returns A GeoMean or GeoMeanApprox atom: a scalar when `axis = NULL`,
#'   otherwise one geometric mean per row or column.
#' @export
geo_mean <- function(x, p = NULL, max_denom = 1024L, approx = TRUE,
                     axis = NULL, keepdims = FALSE) {
  if (approx) {
    GeoMeanApprox(x, p = p, max_denom = max_denom, axis = axis, keepdims = keepdims)
  } else {
    GeoMean(x, p = p, max_denom = max_denom, axis = axis, keepdims = keepdims)
  }
}
